<?php
/** Selected contact/list/tag/alias snapshot shared by offline import comparisons. */
function j_snapshot($db){$fields=array('id','first_name','last_name','business_name','phone_number','email','email_lower','email_source','country','website','city','notes','custom_fields','has_consented','is_opted_out','is_email_opted_out','lead_status');$out=array('contacts'=>array());foreach($db->select('contacts',array(),2147483647) as $c){$out['contacts'][]=array_intersect_key($c,array_flip($fields));}foreach(array('tags'=>array('tags',array('id','name')),'tag_links'=>array('contact_tags',array('contact_id','tag_id')),'lists'=>array('contact_lists',array('id','name','contact_count')),'members'=>array('contact_list_members',array('list_id','contact_id')),'aliases'=>array('email_contact_addresses',array('contact_id','email_address'))) as $key=>$spec){$out[$key]=array();foreach($db->select($spec[0],array(),2147483647) as $r){$out[$key][]=array_intersect_key($r,array_flip($spec[1]));}}return $out;}
